'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#ic-${name}"></use></svg>`;
const btn=(label,action,kind='',ic='',disabled=false)=>`<button class="btn ${kind}" data-action="${esc(action)}" ${disabled?'disabled':''}>${ic?icon(ic):''}${esc(label)}</button>`;
const badge=s=>`<span class="status-pill ${/healthy|recovered|ready_for_review|pass|live_verified/i.test(s)?'good':/fail|blocked|error|issue|degraded/i.test(s)?'bad':'neutral'}">${esc(String(s??'Unknown').replaceAll('_',' '))}</span>`;
const header=(k,t,sub,actions='')=>`<div class="pagehead"><div><div class="eyebrow">${esc(k)}</div><h1>${esc(t)}</h1><p>${esc(sub)}</p></div><div class="page-actions">${actions}</div></div>`;
const kpi=(label,value,detail,ic,cls='')=>`<div class="card kpi"><div class="kpi-top"><span>${esc(label)}</span><span class="kpi-icon ${cls}">${icon(ic)}</span></div><div class="kpi-value">${esc(value)}</div><div class="kpi-foot">${esc(detail)}</div></div>`;
const when=v=>v?new Date(v).toLocaleString(undefined,{timeZone:'Africa/Kigali',dateStyle:'medium',timeStyle:'short'}):'Not recorded';
const code=v=>`<pre class="codebox">${esc(typeof v==='string'?v:JSON.stringify(v,null,2))}</pre>`;
const views={overview:'Overview',projects:'Projects',sandbox:'Sandbox Studio',incidents:'Incident Center',support:'AI Support',maintenance:'Maintenance',developer:'Developer API',settings:'Settings',documentation:'Documentation',audit:'Audit Trail'};
let auth=sessionStorage.getItem('rescue-token')||'',page='overview',data=null,assets=[],studio=null,meta=null,prefs=null,selectedProject=sessionStorage.getItem('rescue-project')||null,project=null,tab='logs',busy=false,conversationId=null,chat=[],conversations=[],tickets=[],keys=[],guideData=[],guideId=null,apiTab='curl',incidentQuery='',incidentFilter='all',selectedAsset=null,challenge=null,themeChoice=localStorage.getItem('rescue-theme')||'dark';
const observations=[];let lastAt=null;
async function api(route,body){const response=await fetch('/api'+route,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+auth,...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)})});const result=await response.json();if(!response.ok){if(response.status===401&&!$('#accessDialog').open)$('#accessDialog').showModal();throw Error(result.error||'Request failed');}return result;}
const v1=(route,body)=>api('/v1'+route,body);
function toast(text,type='ok'){const el=document.createElement('div');el.className='toast '+type;el.textContent=text;$('#toastStack').append(el);setTimeout(()=>el.remove(),5000);}
function applyTheme(choice){themeChoice=choice;localStorage.setItem('rescue-theme',choice);const resolved=choice==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):choice;document.body.dataset.theme=resolved;document.documentElement.dataset.theme=resolved;$('#quickTheme use').setAttribute('href',resolved==='dark'?'#ic-moon':'#ic-sun');}
function download(name,value,type='application/json'){const url=URL.createObjectURL(new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function load(){[data,studio,meta,prefs]=await Promise.all([api('/status'),v1('/studio'),v1('/meta/status'),v1('/settings')]);assets=(await v1('/assets')).assets;if(selectedProject){project=await v1('/sandboxes/'+selectedProject);}if(page==='audit')data.audit=await api('/audit');if(data.lab.at!==lastAt){lastAt=data.lab.at;observations.push({latency:data.lab.checks[0]?.latencyMs||0,healthy:data.lab.healthy,at:lastAt});if(observations.length>30)observations.shift();}$('.workspace-switch strong').textContent=prefs.workspaceName;$('#projectCount').textContent=assets.length+studio.projects.length;$('#incidentCount').textContent=data.incidents.filter(i=>!['recovered','interrupted'].includes(i.status)).length;}
async function navigate(next){if(!views[next])next='overview';page=next;history.replaceState(null,'','#'+next);$('#app').classList.remove('mobile-open');$('#mobileMenu').setAttribute('aria-expanded','false');$('#view').innerHTML='<div class="empty-state">Loading workspace…</div>';try{if(!data)await load();if(page==='support'){[conversations,tickets]=await Promise.all([v1('/support/conversations').then(r=>r.conversations),v1('/support/tickets').then(r=>r.tickets)]);}if(page==='developer')keys=(await v1('/developer-keys')).keys;if(page==='documentation'&&!guideData.length)guideData=(await v1('/guides')).guides;if(page==='audit')data.audit=await api('/audit');render();}catch(e){$('#view').innerHTML=`<div class="screen-error">${esc(e.message)} ${btn('Retry','refresh')}</div>`;}window.scrollTo({top:0,behavior:'instant'});}
function render(){if(!data)return;$('#view').innerHTML=({overview,projects,sandbox,incidents,support,maintenance,developer,settings,documentation,audit}[page])();$('#pageCrumb').textContent=views[page];document.querySelectorAll('.nav-item').forEach(n=>{n.classList.toggle('active',n.dataset.page===page);n.setAttribute('aria-current',n.dataset.page===page?'page':'false');});if(page==='support')$('#chatMessages').scrollTop=$('#chatMessages').scrollHeight;}
async function operation(label,fn){if(busy)return;busy=true;const progress=document.createElement('div');progress.className='progress-banner';progress.setAttribute('role','status');progress.textContent=label;$('.topbar').after(progress);document.querySelectorAll('#view button,.modal button').forEach(b=>{if(!b.disabled){b.dataset.restoreEnabled='true';b.disabled=true;}});try{await fn();await load();render();}catch(e){toast(e.message,'warn');}finally{busy=false;progress.remove();document.querySelectorAll('[data-restore-enabled]').forEach(b=>{b.disabled=false;delete b.dataset.restoreEnabled;});}}
function modal(title,description,body,footer=''){const oldFocus=document.activeElement;$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle" tabindex="-1"><div class="modal-header"><div><h2 id="modalTitle">${esc(title)}</h2><p>${esc(description)}</p></div>${btn('Close','closeModal','clean','close')}</div><div class="modal-body">${body}</div><div class="modal-footer">${footer||btn('Close','closeModal')}</div></div></div>`;$('#modalRoot').returnFocus=oldFocus;$('#app').inert=true;$('#modalRoot .modal').focus();}
function closeModal(){if(busy)return;$('#app').inert=false;$('#modalRoot').innerHTML='';$('#modalRoot').returnFocus?.focus();}
function trend(){const max=Math.max(10,...observations.map(o=>o.latency));return `<svg class="trend-chart" viewBox="0 0 650 205" role="img" aria-label="Actual lab latency in milliseconds during this session">${[35,75,115,155].map(y=>`<path d="M48 ${y}H632" class="chart-grid"/>`).join('')}<text x="4" y="37" class="chart-label">${max}ms</text><text x="9" y="157" class="chart-label">0</text><path d="${observations.map((o,i)=>(i?'L':'M')+(48+i*584/Math.max(1,observations.length-1))+' '+(155-o.latency/max*120)).join(' ')}" fill="none" stroke="#35d69b" stroke-width="2.6"/><text x="48" y="199" class="chart-label">${observations.length} actual probes · ${when(observations.at(-1)?.at)}</text></svg>`;}
function overview(){const active=data.incidents.filter(i=>!['recovered','interrupted'].includes(i.status));return `${header('COMMAND CENTER','Reliability, without the guesswork.','Monitor services, investigate incidents, and recover with verifiable evidence — one unified workspace.',btn('Open Sandbox','go|sandbox','primary','flask')+btn('Add project','addProject','','plus'))}<div class="notice-card"><span class="notice-icon">${icon(active.length?'alert':'shield')}</span><div><strong>${active.length?'An incident needs your attention':'Your incident response workspace is ready'}</strong><small>Run a controlled failure in Sandbox Studio to experience the full detect → diagnose → approve → verify flow.</small></div>${btn('View lab','go|sandbox','small')}</div><div class="kpi-grid">${kpi('Connected projects',String(assets.length+studio.projects.length).padStart(2,'0'),'Observed websites and saved sample projects','layers')}${kpi('Lab service health',data.lab.healthy?'Healthy':'Degraded','Actual health and checkout probes','pulse',data.lab.healthy?'green':'red')}${kpi('Open incidents',String(active.length).padStart(2,'0'),'Recorded disposable lab incidents','alert')}${kpi('Verified recoveries',data.incidents.filter(i=>i.status==='recovered').length+studio.projects.reduce((n,p)=>n+(p.receipts||[]).filter(r=>r.recovered).length,0),'Persisted independent verification receipts','shield','green')}</div><div class="dashboard-grid"><section class="card pad"><div class="card-head"><div><h2>System health trend</h2><p>Actual lab response latency · current browser session</p></div><span class="mini-badge">LIVE OBSERVATIONS</span></div><div class="chart-canvas">${trend()}</div><div class="legend"><span><i></i> Health response · milliseconds</span></div></section><section class="card pad"><div class="card-head"><div><h2>Infrastructure status</h2><p>Public observations and local sample service</p></div>${btn('View all','go|projects','small')}</div>${assets.slice(0,3).map(a=>serviceRow(a.name,new URL(a.url).hostname,a.probes[0]?(a.probes[0].healthy?'Healthy':'Degraded'):'Not checked')).join('')}${serviceRow('Demo Checkout API','Trusted local sample',data.lab.healthy?'Healthy':'Degraded')}</section></div><div class="dashboard-bottom"><section class="card pad"><div class="card-head"><div><h2>Recent incidents</h2><p>Persisted detection and recovery records</p></div>${btn('Incident Center','go|incidents','small')}</div>${data.incidents.slice(0,3).map(i=>`<button class="incident-row full-width" data-action="incident|${i.id}"><span class="service-ico">${icon('alert')}</span><div class="incident-text"><strong>${esc(i.title)}</strong><small>${esc(i.id.slice(0,8))} · Local lab</small></div>${badge(i.status)}</button>`).join('')||'<p class="muted tiny">No incidents yet.</p>'}</section><section class="card pad"><div class="card-head"><div><h2>Quick actions</h2><p>Start your guided recovery</p></div></div><div class="record-list">${btn('Launch Sandbox Studio','go|sandbox','wide primary','flask')}${btn('Talk to AI Support','go|support','wide','message')}${btn('Connect an application','addProject','wide','plus')}</div><div class="hr"></div><div class="feature-split"><span class="kpi-icon green">${icon('shield')}</span><div><strong class="tiny">Proof before claims</strong><div class="muted tiny">All repairs require approval and verification.</div></div></div></section></div>`;}
function serviceRow(name,url,status){return `<div class="service-row"><span class="service-ico">${icon('server')}</span><div class="service-text"><strong>${esc(name)}</strong><small>${esc(url)}</small></div>${badge(status)}</div>`;}
function projects(){return `${header('ASSET MANAGEMENT','Your connected projects','Connect a website for public checks. Domain verification is required before recurring monitoring.',btn('New project','addProject','primary','plus'))}<div class="project-grid">${assets.map(a=>`<div class="card project-card"><div class="project-top"><span class="project-logo">${icon('globe')}</span>${badge(a.probes[0]?(a.probes[0].healthy?'Healthy':'Degraded'):'Not checked')}</div><div><h3>${esc(a.name)}</h3><p>${esc(a.url)}</p></div><div class="muted tiny">Website · ${a.owned?'Ownership verified':'Public observation only'}</div><div class="project-stats"><div><span>Recorded checks</span><strong>${a.maintenance.recordedChecks}</strong></div><div><span>Latency</span><strong>${a.probes[0]?.latencyMs??'—'}ms</strong></div><div><span>Monitoring</span><strong>${a.monitoring?'On':'Off'}</strong></div></div>${btn('View project','asset|'+a.id,'wide','arrow')}</div>`).join('')}${studio.projects.map(p=>`<div class="card project-card"><div class="project-top"><span class="project-logo">${icon('flask')}</span>${badge(p.state)}</div><div><h3>${esc(p.name)}</h3><p>Trusted IRIZA sample checkout</p></div><div class="muted tiny">Disposable sample · ${esc(p.id.slice(0,8))}</div>${badge(p.gate.decision)}${btn('Open sandbox','project|'+p.id,'wide','arrow')}</div>`).join('')}</div><section class="section-space card pad"><div class="card-head"><div><h2>Connect your next application</h2><p>Only supported, authorized connections can be enabled.</p></div></div><div class="connect-panel"><button class="connect-option" data-action="addProject"><span class="service-ico">${icon('globe')}</span><strong>Website URL</strong><span>Safe public checks. Prove domain ownership for recurring monitoring.</span></button><button class="connect-option" disabled title="Scoped GitHub App enrollment is not available"><span class="service-ico">${icon('github')}</span><strong>GitHub repository</strong><span>Unavailable · secure repository authorization and runner required.</span></button><button class="connect-option" disabled title="Authenticated telemetry adapter is not available"><span class="service-ico">${icon('server')}</span><strong>Application agent</strong><span>Unavailable · signed enrollment is required.</span></button></div></section>`;}
function sandbox(){const p=project,broken=p&&!p.observation?.healthy,proposal=p?.proposal,receipt=p?.receipts?.[0],verified=receipt?.recovered&&p?.gate.decision==='READY_FOR_REVIEW';const phase=verified?4:proposal?2:broken?1:-1;return `${header('CONTROLLED TEST ENVIRONMENT','Sandbox & Recovery Studio','Real sample runtime, independent tests, live Meta investigation and approval-controlled recovery.',btn('Create sandbox','createSandbox','','plus')+(p?btn('Reset sample','sandboxOp|reset','','refresh'):''))}<div class="workspace-toolbar control-row"><label for="sandboxSelect">Saved environment</label><select id="sandboxSelect"><option value="">Choose a sandbox</option>${studio.projects.map(s=>`<option value="${esc(s.id)}" ${p?.id===s.id?'selected':''}>${esc(s.name)} · ${esc(s.state)}</option>`).join('')}</select>${p?btn(p.preview?'Stop preview':'Launch preview',p.preview?'sandboxOp|stop':'sandboxOp|launch','','play'):''}${btn('Create & launch','createSandbox','primary','plus')}${btn(studio.emergencyStop?'Resume sandbox changes':'Emergency stop','emergency','', 'shield')}</div><div class="notice-card"><span class="notice-icon">${icon('flask')}</span><div><strong>${esc(p?.name||'Choose a disposable checkout service')}</strong><small>Trusted local Node.js sample · synthetic data · no production credentials or arbitrary code execution.</small></div>${badge(p?.state||'Not started')}</div><div class="stage-grid"><section class="card pad"><div class="card-head"><div><h2>Application preview</h2><p>Actual disposable application; read-only preview</p></div><span class="mini-badge">${esc(p?.id.slice(0,8)||'LOCAL')}</span></div><div class="lab-window"><div class="browser-bar"><span class="traffic-lights"><i></i><i></i><i></i></span><div class="url-display">${esc(p?.preview?'Local preview / '+p.id.slice(0,8):'Preview stopped')}</div>${icon('refresh','sm')}</div>${p?.preview?`<iframe class="runtime-frame" title="Live sample checkout" src="${esc(p.preview)}" sandbox="allow-same-origin"></iframe>`:`<div class="preview-empty"><h3>Start a disposable environment</h3><p class="muted tiny">Create or select a sample, then launch its preview.</p></div>`}</div><div class="section-space sandbox-toolbar">${btn('Inject 502 failure','injectFault','danger','alert',!p?.preview||broken)}${btn('Run tests','sandboxOp|tests','','play',!p?.preview)}${btn('Analyze with AI','sandboxOp|diagnose','primary','zap',!p?.preview||!broken)}${btn('Verify repair','sandboxOp|tests','success','check',!p?.preview)}${btn('Download receipt','report','','download',!p)}</div></section><section class="card pad"><div class="card-head"><div><h2>Recovery workflow</h2><p>Approval-controlled state machine</p></div>${badge(p?.gate.decision||'NEEDS_REVIEW')}</div><div class="pipeline">${[0,1,2,3].map(i=>`<div class="pipeline-step ${i<phase?'done':i===phase?'current':''}"></div>`).join('')}</div>${['Inject controlled failure','Run Meta AI diagnosis','Approve safe repair','Verify independent tests'].map((s,i)=>`<div class="workflow-step"><div class="step-num ${i<phase?'done':i===phase?'active':''}">${i<phase?icon('check','sm'):i+1}</div><div><strong>${s}</strong><small>${['HTTP 502 in a disposable service','Sanitized evidence and read-only tools','Exact proposal; explicit human approval','Health and checkout must pass'][i]}</small></div></div>`).join('')}<div class="hr"></div><div class="subhead">Release gate</div><div class="feature-split">${icon(verified?'shield':broken?'alert':'clock','lg')}<div><strong>${esc(p?.gate.decision||'AWAITING RELEASE TESTS')}</strong><div class="muted tiny">${esc(p?.gate.reasons?.join(' ')||'Create or select an environment to begin.')}</div></div></div></section></div><div class="cols-2"><section class="card"><div class="tab-bar">${[['logs','Runtime logs'],['tests','Test results'],['evidence','Evidence'],['history','History']].map(([id,name])=>`<button data-action="tab|${id}" class="tab ${tab===id?'active':''}">${name}</button>`).join('')}</div><div class="card pad">${sandboxEvidence()}</div></section><div><section class="card pad"><div class="card-head"><div><h2>AI recovery assistant</h2><p>${esc(meta.model)} · ${esc(meta.connection)}</p></div>${icon('brain-circuit')}</div>${proposal?`<p class="muted tiny">${esc(proposal.summary)}</p><div class="hr"></div>${badge(proposal.provider==='meta'?'LIVE META':'LOCAL RULES')}<p class="mono tiny">${esc(proposal.actionId)}</p><p class="muted tiny">${esc(proposal.uncertainty)}</p>${code(proposal.patch)}${btn('Review & approve','reviewRepair','primary small','shield')}<details><summary>Model provenance and evidence tools</summary>${code({requestId:proposal.requestId,usage:proposal.usage,hypotheses:proposal.hypotheses,toolTrace:proposal.toolTrace})}</details>`:`<p class="muted tiny">${broken?'A controlled fault is active. Analyze with AI to investigate actual evidence.':'Inject a controlled failure to begin. Meta never executes or approves a repair.'}</p>`}${receipt?`<div class="hr"></div>${badge(receipt.recovered?'Verified recovery':'Verification failed')}<p class="muted tiny">${when(receipt.at||receipt.completedAt)}</p>`:''}${p?.error?`<p class="inline-error">${esc(p.error)}</p>`:''}</section></div></div>`;}
function sandboxEvidence(){if(!project)return '<p class="muted tiny">Choose an environment to view actual evidence.</p>';if(tab==='logs')return code(project.logs?.map(l=>`${l.at} ${l.event} ${l.route||''} ${l.status||''}`).join('\n')||'No logs recorded.');if(tab==='tests'){const run=project.runs[0];return run?run.results.map(t=>`<div class="test-row"><div><strong>${esc(t.name)}</strong><small>${esc(t.note||'Recorded independent test')} · ${t.required?'required':'optional'}</small></div>${badge(t.status)}</div>`).join(''):'<p class="muted tiny">Run tests to collect actual results.</p>';}if(tab==='history')return project.history.map(e=>`<div class="timeline-row"><strong>${esc(e.type)}</strong><small>${when(e.at)}</small></div>`).join('')+project.snapshots.map(s=>`<div class="test-row"><span>${esc(s.label)}</span>${btn('Restore snapshot','rollback|'+s.id,'small','refresh',!project.preview)}</div>`).join('');return code({projectId:project.id,buildHash:project.buildHash,revision:project.revision,observation:project.observation,gate:project.gate,receipt:project.receipts[0]});}
function incidents(){const records=data.incidents.filter(i=>(i.title+' '+i.id+' '+i.status).toLowerCase().includes(incidentQuery.toLowerCase())&&(incidentFilter==='all'||(incidentFilter==='active'?!['recovered','interrupted'].includes(i.status):i.status===incidentFilter)));return `${header('INCIDENT OPERATIONS','Incident Center','Review recorded incident timelines, investigation status and independent recovery evidence.',btn('Test a failure','go|sandbox','primary','flask'))}<div class="card pad"><div class="card-head"><div><h2>Incident register</h2><p>${records.length} matching persisted incidents</p></div><span class="mini-badge">LOCAL SQLITE</span></div><div class="data-filter"><input id="incidentSearch" aria-label="Search incidents" placeholder="Search incidents…" value="${esc(incidentQuery)}"><select id="incidentStatus" aria-label="Incident status">${['all','active','recovered','interrupted','awaiting_approval','diagnosis_failed'].map(v=>`<option ${v===incidentFilter?'selected':''}>${v}</option>`).join('')}</select></div><div class="table-scroll"><table class="history-table"><thead><tr><th>INCIDENT</th><th>SERVICE</th><th>SEVERITY</th><th>STATUS</th><th>WHEN</th><th></th></tr></thead><tbody>${records.map(i=>`<tr><td><strong>${esc(i.title)}</strong><div class="incident-ref">${esc(i.id)}</div></td><td>Disposable lab</td><td>${badge('Critical workflow')}</td><td>${badge(i.status)}</td><td class="muted">${when(i.createdAt)}</td><td>${btn('Inspect','incident|'+i.id,'small')}</td></tr>`).join('')||'<tr><td colspan="6">No matching incidents</td></tr>'}</tbody></table></div></div><div class="section-space two-panels"><div class="card pad"><div class="card-head"><h2>Severity guide</h2></div><p class="muted tiny">Critical — a core workflow is unavailable.<br><br>These lab incidents are deliberately staged against synthetic sample services. Public website incidents remain separately recorded in Maintenance.</p></div><div class="gradient-info"><div class="eyebrow">PROOF-CARRYING RECOVERY</div><h2>Evidence over assumptions.</h2><p>Each recovery links observed symptoms, model evidence, approval and independent verification.</p>${btn('Explore the recovery lab','go|sandbox','primary','arrow')}</div></div>`;}
function support(){return `${header('ASSISTED TROUBLESHOOTING','AI Support Center','Ask questions using authorized evidence. Real Meta requests run server-side; unavailable inference returns an error.',btn('Open Sandbox','go|sandbox','','flask'))}<div class="support-shell"><aside class="support-aside">${btn('New conversation','newChat','wide','plus')}<div class="subhead">RECENT CONVERSATIONS</div>${conversations.map(c=>`<button class="support-thread ${conversationId===c.id?'active':''} full-width" data-action="conversation|${c.id}">Conversation ${esc(c.id.slice(0,8))}<small>${when(c.created_at)}</small></button>`).join('')||'<p class="muted tiny">No saved conversations yet.</p>'}<div class="hr"></div><div class="muted tiny">${icon('shield','sm')} Read-only AI assistance. Never paste passwords or API keys.</div></aside><section class="support-main"><div class="support-top"><div><strong>IRIZA RESCUE AI</strong><div class="muted tiny">${esc(meta.model)} · saved conversations</div></div>${badge(meta.connection)}</div><div class="support-messages" id="chatMessages">${chat.length?chat.map(m=>`<div class="chat-message ${m.role==='user'?'user':'agent'}"><strong>${m.role==='user'?'YOU':m.provider==='meta'?'IRIZA AI · LIVE META':'IRIZA SUPPORT'}</strong><p>${esc(m.text||m.answer)}</p>${m.requestId?`<small>${esc(m.requestId)} · ${m.usage?.total_tokens??'unknown'} tokens</small>`:''}</div>`).join(''):'<div class="chat-message agent"><strong>IRIZA SUPPORT</strong><p>Describe the issue or select a sample project for evidence-grounded guidance. Repairs always require separate approval.</p></div>'}</div><div class="card pad"><div class="control-row"><label for="chatLanguage">Language</label><select id="chatLanguage"><option value="en" ${prefs.language==='en'?'selected':''}>English</option><option value="fr" ${prefs.language==='fr'?'selected':''}>Français</option></select><label for="chatContext">Evidence</label><select id="chatContext"><option value="">Workspace guides</option>${project?`<option value="sandbox:${project.id}">Selected sample: ${esc(project.name)}</option>`:''}${assets.map(a=>`<option value="asset:${a.id}">${esc(a.name)} · public evidence</option>`).join('')}</select></div><div class="tip-row">${btn('Test Muse connection','testMeta','small','zap')}${btn('Open Sandbox Studio','go|sandbox','small','flask')}${btn('Escalate to local ticket','ticket','small','document')}</div></div><form class="support-compose" id="chatForm"><input id="chatInput" placeholder="Describe a technical issue…" aria-label="Support message" maxlength="2000" required minlength="3"><button class="btn primary" type="submit" ${busy?'disabled':''}>Send ${icon('arrow','sm')}</button></form></section></div><section class="card pad section-space"><div class="card-head"><h2>Local support tickets</h2>${btn('New ticket','ticket','small','plus')}</div>${tickets.map(t=>`<div class="test-row"><div><strong>${esc(t.title)}</strong><small>${esc(t.state)}</small></div>${btn('Review','ticketView|'+t.id,'small')}</div>`).join('')||'<p class="muted tiny">No local tickets. Escalation saves a record here; it does not contact an external team.</p>'}</section>`;}
function maintenance(){return `${header('PREVENTIVE OPERATIONS','Maintenance Center','Read-only HTTP and TLS observations, domain ownership and recurring monitoring preferences.',btn('Refresh records','refresh','primary','refresh'))}<div class="kpi-grid">${kpi('Registered monitors',assets.length,'Public HTTPS assets','server')}${kpi('Current ownership',assets.filter(a=>a.owned).length,'Verified domain proofs','shield','green')}${kpi('Open website incidents',assets.reduce((n,a)=>n+a.incidents.filter(i=>i.state==='OPEN').length,0),'Repeated failed public observations','alert')}${kpi('Scheduled monitors',assets.filter(a=>a.monitoring).length,'Requires current ownership proof','pulse')}</div><div class="section-space cols-2"><section class="card pad"><div class="card-head"><div><h2>Monitoring schedule</h2><p>Actual observations; retained history only</p></div></div>${assets.map(a=>`<div class="test-row"><div><strong>${esc(a.name)}</strong><small>${a.monitoring?'Every '+a.interval_seconds+' seconds':'Manual checks'} · ${a.probes[0]?when(a.probes[0].at):'Not checked'}</small><div class="asset-health-strip">${a.probes.slice(0,35).reverse().map(o=>`<i class="${o.healthy?'':'bad'}" title="${esc(when(o.at))} HTTP ${o.status}"></i>`).join('')}</div></div>${btn('Inspect','asset|'+a.id,'small')}</div>`).join('')||'<p>No assets registered.</p>'}</section><section class="card pad"><div class="card-head"><div><h2>Maintenance recommendations</h2><p>Derived from current recorded evidence</p></div></div>${assets.map(a=>`<div class="test-row"><div><strong>${esc(a.name)}</strong><small>${a.owned?'Ownership verified':'Verify domain ownership before scheduling'}<br>TLS: ${a.maintenance.tlsDaysRemaining===null?'No expiry evidence':a.maintenance.tlsDaysRemaining+' days remaining'}<br>${a.probes[0]?.healthy?'Latest public check passed':'Review failed or missing HTTP observation'}</small></div>${badge(a.probes[0]?.healthy?'Healthy':'Needs review')}</div>`).join('')}</section></div><div class="section-space gradient-info"><div class="eyebrow">MAINTENANCE PHILOSOPHY</div><h2>Prevent the next incident.</h2><p>Monitoring is read-only. A public URL never grants source, private logs, SSH, database or production repair access.</p>${btn('View Developer API','go|developer','','code')}</div>`;}
const snippets=()=>({curl:'curl -H "Authorization: Bearer YOUR_READ_KEY" \\\n  http://127.0.0.1:4310/api/v1/sandboxes',js:'const response = await fetch("http://127.0.0.1:4310/api/v1/sandboxes", {\n  headers: { Authorization: "Bearer YOUR_READ_KEY" }\n});\nconst result = await response.json();',response:JSON.stringify({projects:studio.projects.map(p=>({id:p.id,name:p.name,state:p.state,gate:p.gate}))},null,2)});
function developer(){return `${header('FOR BUILDERS','Developer API','Authenticated local API. Scoped report keys expire in 24 hours and cannot approve or execute repairs.',btn('Copy example','copySnippet','','copy'))}<div class="notice-card"><span class="notice-icon">${icon('shield')}</span><div><strong>Secure integrations by design</strong><small>Hashed credentials · Expiry and revocation · Read-only scope · Approval-gated recovery</small></div>${badge('Local API')}</div><div class="cols-2"><section class="card pad"><div class="card-head"><div><h2>API playground</h2><p>Working local request and genuine returned project data</p></div></div><div class="tab-bar">${[['curl','cURL'],['js','JavaScript'],['response','Actual JSON']].map(([id,label])=>`<button class="tab ${apiTab===id?'active':''}" data-action="apiTab|${id}">${label}</button>`).join('')}</div>${code(snippets()[apiTab])}<div class="section-space">${btn('Try endpoint','tryEndpoint','primary','play')} ${btn('Copy code','copySnippet','','copy')}</div></section><section class="card pad"><div class="card-head"><div><h2>Implemented API routes</h2><p>OpenAPI lists exact request and response contracts.</p></div></div>${[['GET','/api/v1/sandboxes','Read project reports'],['POST','/api/v1/sandboxes','Operator: create trusted sample'],['GET','/api/v1/sandboxes/{id}/report','Read actual tests, receipts and gate'],['POST','/api/v1/sandboxes/{id}/diagnose','Operator: investigate failing evidence'],['POST','/api/v1/sandboxes/{id}/approve','Operator: approve exact bound proposal'],['GET','/api/v1/openapi','Read API specification']].map(([method,url,text])=>`<div class="api-block"><div><span class="method ${method==='POST'?'post':''}">${method}</span> <span class="mono tiny">${esc(url)}</span></div><div class="muted tiny">${text}</div></div>`).join('')}</section></div><div class="section-space two-panels"><div class="card pad"><div class="card-head"><h2>Developer keys</h2>${btn('Create key','createKey','small primary','plus')}</div>${keys.map(k=>`<div class="test-row"><div><strong>${esc(k.id.slice(0,12))}</strong><small>${k.revoked?'Revoked':'Expires '+when(k.expires)}</small></div>${btn('Revoke','revoke|'+k.id,'small','',!!k.revoked)}</div>`).join('')||'<p class="muted tiny">No developer keys created.</p>'}</div><div class="card pad"><h3>Integration contracts</h3><p class="muted tiny">Scope sandbox:read. Keys cannot access previews, support messages, Meta connection tests or mutations.</p><div class="control-row">${btn('OpenAPI JSON','downloadOpenapi','','download')}${btn('TypeScript SDK','downloadSdk','','download')}${btn('User guides','go|documentation','','document')}</div></div></div>`;}
function settings(){return `${header('PREFERENCES','Workspace Settings','Personalize your local workspace. Settings are persisted in the existing SQLite database.',btn('Lock workspace','lock','','shield'))}<form id="settingsForm" class="settings-form"><div class="cols-2"><section class="card pad"><div class="card-head"><h2>Appearance</h2>${icon('sun')}</div><p class="muted tiny">Choose dark, light or your system preference.</p><div class="theme-chooser">${[['dark','Dark'],['light','Light'],['system','System']].map(([id,label])=>`<button type="button" class="theme-choice ${themeChoice===id?'selected':''}" data-action="theme|${id}">${label}</button>`).join('')}</div><div class="hr"></div><div class="subhead">Workspace identity</div><div class="field"><label for="orgName">Organization name</label><input id="orgName" required minlength="2" maxlength="60" value="${esc(prefs.workspaceName)}"></div><div class="field"><label for="operatorName">Operator display name</label><input id="operatorName" required minlength="2" maxlength="60" value="${esc(prefs.displayName)}"></div><button class="btn primary" type="submit">${icon('check')} Save preferences</button></section><section class="card pad"><div class="card-head"><h2>Notifications and monitoring</h2>${icon('bell')}</div><div class="setting-row"><div><strong>Incident alerts</strong><small>Display active workspace incidents</small></div><input type="checkbox" id="incidentAlerts" aria-label="Incident alerts" ${prefs.incidentAlerts?'checked':''}></div><div class="setting-row"><div><strong>Email notifications</strong><small>Unavailable · no mail provider connected</small></div><button class="switch" disabled aria-label="Email notifications unavailable"></button></div><div class="setting-row"><div><strong>Scheduled website checks</strong><small>Configure each ownership-verified website in Maintenance</small></div>${btn('Manage','go|maintenance','small')}</div><div class="field"><label for="languagePreference">Support language</label><select id="languagePreference"><option value="en" ${prefs.language==='en'?'selected':''}>English</option><option value="fr" ${prefs.language==='fr'?'selected':''}>Français</option></select></div></section></div></form><div class="section-space card pad"><div class="card-head"><h2>Environment safety</h2></div><div class="two-panels"><div><strong class="tiny">Approval-controlled execution</strong><p class="muted tiny">Fixed trusted Node.js samples only. Meta reads sanitized evidence and proposes allowlisted actions. Human approval is separate.</p></div><div><strong class="tiny">Original IRIZA identity</strong><p class="muted tiny">Original IRIZA TASTE logo preserved. The rest of this interface follows your approved prototype. Production systems and DNS remain unchanged.</p></div></div></div>`;}
function documentation(){const guide=guideData.find(g=>g.id===guideId)||guideData[0];return `${header('KNOWLEDGE BASE','Documentation','Step-by-step guides, source books and API contracts.',btn('Source books','references','','document'))}<div class="cols-2"><aside class="card pad"><label for="guideSearch">Search guides</label><input id="guideSearch" placeholder="Recovery, Meta, monitoring…"><div class="guide-list section-space">${guideData.map(g=>btn(g.title,'guide|'+g.id,'wide')).join('')}</div></aside><article class="card pad guide-copy"><div class="eyebrow">${esc(guide?.category||'Guide')}</div><h1>${esc(guide?.title||'No guide')}</h1>${guide?renderGuide(guide):''}</article></div>`;}
function renderGuide(g){return (g.steps||[]).map((s,i)=>`<p>${i+1}. ${esc(s)}</p>`).join('')+(g.body?`<p>${esc(g.body)}</p>`:'')+(g.sections||[]).map(s=>`<h3>${esc(s.title)}</h3><p>${esc(s.body||s.text)}</p>`).join('')+code(g.content||g.paragraphs||g.description||g)+btn('Download guide','downloadGuide','','download');}
function audit(){return `${header('ACCOUNTABILITY','Audit Trail','Locally persisted SHA-256 chained events; no external signature claim.',btn('Export JSON','downloadAudit','','download'))}<section class="card pad">${badge(data.audit?.valid?'Hash chain valid':'Verification required')}<div class="record-list section-space">${data.audit?.events.slice().reverse().slice(0,100).map(e=>`<details><summary>${esc(e.event.type)} · ${when(e.event.at)}</summary>${code(e)}</details>`).join('')||'<p>No events loaded.</p>'}</div></section>`;}
function addProject(){modal('Connect a project','Public HTTPS observations only. No production repair access.',`<form id="projectForm"><div class="field"><label for="projectName">Project name</label><input id="projectName" required minlength="2" maxlength="70"></div><div class="field"><label for="projectUrl">Public HTTPS website URL</label><input id="projectUrl" type="url" required placeholder="https://example.com/"></div></form>`,btn('Cancel','closeModal')+'<button class="btn primary" type="submit" form="projectForm">Add & check website</button>');}
function createSandbox(){modal('Create sandbox','Launch the existing trusted local sample. Arbitrary repository execution is unavailable.',`<form id="sandboxForm"><div class="field"><label for="sandboxName">Project name</label><input id="sandboxName" required minlength="2" maxlength="70" value="Release candidate"></div><div class="field"><label for="sandboxTtl">Lifetime</label><select id="sandboxTtl"><option value="15">15 minutes</option><option value="30" selected>30 minutes</option><option value="60">60 minutes</option></select></div><div class="notice-card"><strong>Node.js sample · synthetic data · no payments</strong></div></form>`,btn('Cancel','closeModal')+'<button class="btn primary" form="sandboxForm" type="submit">Create & launch</button>');}
function reviewRepair(){const p=project?.proposal;if(!p)throw Error('Investigate a failure first');modal('Approve sandbox-only repair','Review this exact change. The model cannot grant approval.',`<p>${esc(p.summary)}</p>${code({action:p.actionId,project:project.name,revision:p.revision,expiresAt:p.expiresAt,patch:p.patch,risk:p.risk,verificationSteps:p.verificationSteps})}<p class="muted tiny">A snapshot is saved first. Health and checkout are independently verified three times. Failed verification triggers rollback.</p>`,btn('Cancel','closeModal')+btn('Approve sandbox repair','confirmRepair','primary','shield'));}
async function inspectIncident(id){const i=await api('/incidents/'+id);modal(i.title,'Persisted local lab incident · '+i.status,`${badge(i.status)}<h3>Observed evidence</h3>${code(i.evidence)}${i.proposal?`<h3>Investigation</h3><p>${esc(i.proposal.summary)}</p>${code({action:i.proposal.action,requestId:i.proposal.requestId,hypotheses:i.proposal.hypotheses,toolTrace:i.proposal.toolTrace})}`:''}${i.receipt?`<h3>Verification receipt</h3>${code(i.receipt)}`:''}${i.error?`<p class="inline-error">${esc(i.error)}</p>`:''}`,btn('Close','closeModal')+(['detected','diagnosis_failed','awaiting_approval'].includes(i.status)?btn('Investigate','investigateIncident|'+id,'','zap'):'')+(i.status==='awaiting_approval'?btn('Approve lab recovery','approveIncident|'+id,'primary','shield'):'')+(i.receipt?btn('Download receipt','incidentReceipt|'+id,'','download'):''));}
async function inspectAsset(id){selectedAsset=id;const a=await v1('/assets/'+id);modal(a.name,'Public evidence only · '+a.url,`${badge(a.probes[0]?(a.probes[0].healthy?'Healthy':'Degraded'):'Not checked')}<div class="test-row"><strong>Ownership</strong><span>${a.owned?'Verified until '+when(a.verified_until):'Not verified'}</span></div><div class="test-row"><strong>TLS expiry</strong><span>${a.maintenance.tlsDaysRemaining??'Unknown'} days</span></div><div class="field"><label for="monitorInterval">Monitoring interval</label><select id="monitorInterval">${[60,300,900].map(n=>`<option value="${n}" ${n===a.interval_seconds?'selected':''}>${n} seconds</option>`).join('')}</select></div><div class="control-row">${btn(a.monitoring?'Disable monitoring':'Enable monitoring','monitorAsset','','pulse',!a.owned&&!a.monitoring)}${btn('DNS ownership proof','challenge|dns')}${btn('File ownership proof','challenge|file')}</div>${challenge&&challenge.assetId===id?`<h3>Publish this ownership proof</h3><p>${esc(challenge.location)}</p>${code(challenge.token)}${btn('Verify published proof','verifyAsset','primary','shield')}`:''}<details><summary>Actual HTTP and TLS observations</summary>${code(a.probes)}</details><div class="record-list">${a.incidents.map(i=>`<p>${esc(i.state)} · ${when(i.detected_at)}</p>`).join('')}</div>`,btn('Close','closeModal')+btn('Check now','probeAsset','','refresh')+btn('Download report','assetReport','','download'));}
function ticketDialog(){modal('Escalate to local ticket','This saves a local record; no external message is sent.',`<form id="ticketForm"><div class="field"><label for="ticketTitle">Title</label><input id="ticketTitle" required minlength="3" maxlength="120"></div><div class="field"><label for="ticketDescription">Evidence and description</label><textarea id="ticketDescription" required minlength="3" maxlength="8000">${esc(chat.at(-1)?.answer||'')}</textarea></div></form>`,btn('Cancel','closeModal')+'<button class="btn primary" type="submit" form="ticketForm">Save ticket</button>');}
async function act(action){const [name,arg]=action.split('|');if(name==='go')return navigate(arg);if(name==='closeModal')return closeModal();if(name==='theme'){applyTheme(arg);if(page==='settings')render();return;}if(name==='tab'){tab=arg;return render();}if(name==='apiTab'){apiTab=arg;return render();}if(name==='guide'){guideId=arg;return render();}if(name==='addProject')return addProject();if(name==='createSandbox')return createSandbox();if(name==='reviewRepair')return reviewRepair();if(name==='ticket')return ticketDialog();if(name==='lock'){auth='';sessionStorage.removeItem('rescue-token');return $('#accessDialog').showModal();}if(name==='copySnippet'){await navigator.clipboard.writeText(snippets()[apiTab]);return toast('Copied code.');}if(name==='newChat'){conversationId=null;chat=[];return render();}if(name==='incident')return inspectIncident(arg);if(name==='asset')return inspectAsset(arg);
 await operation('Working on '+name.replaceAll(/([A-Z])/g,' $1').toLowerCase()+'…',async()=>{
  if(name==='refresh'){if(page==='support'){conversations=(await v1('/support/conversations')).conversations;tickets=(await v1('/support/tickets')).tickets;}return;}
  if(name==='project'){selectedProject=arg;project=await v1('/sandboxes/'+arg);page='sandbox';history.replaceState(null,'','#sandbox');}
  else if(name==='sandboxOp'){if(!project)throw Error('Choose a sample project');await v1('/sandboxes/'+project.id+'/'+arg,{});if(arg==='tests')tab='tests';}
  else if(name==='injectFault'){await v1('/sandboxes/'+project.id+'/inject',{scenario:'stopped_backend'});tab='tests';}
  else if(name==='confirmRepair'){const p=project.proposal;await v1('/sandboxes/'+project.id+'/approve',{proposalId:p.id,nonce:p.nonce,digest:p.digest});$('#app').inert=false;$('#modalRoot').innerHTML='';tab='tests';}
  else if(name==='rollback'){await v1('/sandboxes/'+project.id+'/rollback',{snapshotId:arg});tab='tests';}
  else if(name==='report')download('rescue-recovery-report.json',await v1('/sandboxes/'+project.id+'/report'));
  else if(name==='emergency'){await v1('/emergency-stop',{enabled:!studio.emergencyStop});}
  else if(name==='testMeta'){const result=await v1('/meta/test',{});toast(`${result.provider} · ${result.model} · ${result.reply} · ${result.requestId}`);}
  else if(name==='conversation'){const c=await v1('/support/conversations/'+arg);conversationId=c.id;chat=c.messages;}
  else if(name==='ticketView'){const t=await v1('/support/tickets/'+arg);modal(t.title,t.state,`<p>${esc(t.description)}</p>${code(t.comments||[])}`,btn('Close','closeModal')+btn('Mark resolved','resolveTicket|'+arg,'primary')+btn('Export','ticketReport|'+arg,'','download'));}
  else if(name==='resolveTicket'){await v1('/support/tickets/'+arg,{state:'RESOLVED'});tickets=(await v1('/support/tickets')).tickets;$('#app').inert=false;$('#modalRoot').innerHTML='';}
  else if(name==='ticketReport')download('rescue-support-ticket.json',await v1('/support/tickets/'+arg));
  else if(name==='tryEndpoint'){await v1('/sandboxes');apiTab='response';toast('Authenticated endpoint responded successfully.');}
  else if(name==='createKey'){const k=await v1('/developer-keys',{});keys=(await v1('/developer-keys')).keys;modal('Copy your read-only key now','Shown once. Expires '+when(k.expires),`<label for="issuedKey">Read-only API key</label><input id="issuedKey" type="password" readonly value="${esc(k.key)}"><p>Scope: sandbox:read</p>`,btn('Close','closeModal')+btn('Reveal key','revealKey')+btn('Copy key','copyKey','','copy'));}
  else if(name==='revealKey')$('#issuedKey').type=$('#issuedKey').type==='password'?'text':'password';
  else if(name==='copyKey'){await navigator.clipboard.writeText($('#issuedKey').value);toast('Copied read-only key.');}
  else if(name==='revoke'){await v1('/developer-keys/'+arg+'/revoke',{});keys=(await v1('/developer-keys')).keys;}
  else if(name==='downloadOpenapi')download('rescue-openapi.json',await v1('/openapi'));
  else if(name==='downloadSdk'){const r=await fetch('/api/v1/sdk',{headers:{Authorization:'Bearer '+auth}});if(!r.ok)throw Error('SDK download failed');download('rescue-client.ts',await r.text(),'text/plain');}
  else if(name==='downloadGuide'){download('rescue-guide.json',guideData.find(g=>g.id===guideId)||guideData[0]);}
  else if(name==='references'){const docs=(await v1('/reference')).documents;modal('Supplied source books','Original project references',docs.map(d=>btn(d.title,'reference|'+d.id,'wide','download')).join(''));}
  else if(name==='reference'){const r=await fetch('/api/v1/reference/'+arg,{headers:{Authorization:'Bearer '+auth}});if(!r.ok)throw Error('Reference unavailable');const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download=r.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||arg;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  else if(name==='downloadAudit')download('rescue-audit.json',await api('/audit'));
  else if(name==='investigateIncident'){await api('/incidents/'+arg+'/investigate',{});await inspectIncident(arg);}
  else if(name==='approveIncident'){const i=await api('/incidents/'+arg);await api('/incidents/'+arg+'/approve',{action:i.proposal.action});await inspectIncident(arg);}
  else if(name==='incidentReceipt')download('rescue-receipt.json',await api('/incidents/'+arg+'/receipt'));
  else if(name==='probeAsset'){await v1('/assets/'+selectedAsset+'/probe',{});await inspectAsset(selectedAsset);}
  else if(name==='assetReport')download('public-observation.json',await v1('/assets/'+selectedAsset+'/report'));
  else if(name==='challenge'){challenge={...await v1('/assets/'+selectedAsset+'/ownership-challenge',{method:arg}),assetId:selectedAsset};await inspectAsset(selectedAsset);}
  else if(name==='verifyAsset'){await v1('/assets/'+selectedAsset+'/verify-ownership',{challengeId:challenge.id});challenge=null;await inspectAsset(selectedAsset);}
  else if(name==='monitorAsset'){const a=assets.find(a=>a.id===selectedAsset);await v1('/assets/'+selectedAsset+'/monitoring',{enabled:!a.monitoring,intervalSeconds:Number($('#monitorInterval').value)});await inspectAsset(selectedAsset);}
  else throw Error('Unsupported action');
 });
}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();if(!a.disabled)act(a.dataset.action).catch(e=>toast(e.message,'warn'));return;}const n=e.target.closest('[data-page]');if(n)navigate(n.dataset.page);});
document.addEventListener('change',e=>{if(e.target.id==='sandboxSelect'){selectedProject=e.target.value||null;if(selectedProject)sessionStorage.setItem('rescue-project',selectedProject);else sessionStorage.removeItem('rescue-project');operation('Opening sample environment…',async()=>{project=selectedProject?await v1('/sandboxes/'+selectedProject):null;});}if(e.target.id==='incidentStatus'){incidentFilter=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='incidentSearch'){const pos=e.target.selectionStart;incidentQuery=e.target.value;render();$('#incidentSearch').focus();$('#incidentSearch').setSelectionRange(pos,pos);}if(e.target.id==='guideSearch'){const term=e.target.value.toLowerCase();document.querySelectorAll('.guide-list button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(term));}if(e.target.id==='quickFind'){const term=e.target.value.toLowerCase();document.querySelectorAll('[data-action^="searchGo|"]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(term));}});
document.addEventListener('submit',async e=>{const id=e.target.id;if(!['accessForm','projectForm','sandboxForm','settingsForm','chatForm','ticketForm'].includes(id))return;e.preventDefault();if(id==='accessForm'){auth=$('#accessToken').value.trim();try{await load();sessionStorage.setItem('rescue-token',auth);$('#accessToken').value='';$('#accessDialog').close();await navigate(location.hash.slice(1)||'overview');}catch(error){$('#accessError').textContent=error.message;}return;}
 const form=e.target;if(!form.reportValidity())return;
 if(id==='chatForm'){if(busy)return;const message=$('#chatInput').value,language=$('#chatLanguage').value,context=$('#chatContext').value;chat.push({role:'user',text:message});$('#chatInput').value='';await operation('Muse is reviewing authorized evidence…',async()=>{try{const [kind,target]=context.split(':');const answer=await v1('/support',{message,language,conversationId,...(kind==='sandbox'?{projectId:target}:kind==='asset'?{assetId:target}:kind==='agent'?{agentId:target}:{})});conversationId=answer.conversationId;chat.push({role:'assistant',...answer});conversations=(await v1('/support/conversations')).conversations;}catch(error){chat.push({role:'assistant',text:'Request failed: '+error.message+'. No repair was performed.'});throw error;}});render();return;}
 const payload=id==='projectForm'?{name:$('#projectName').value,url:$('#projectUrl').value}:id==='sandboxForm'?{source:'demo',name:$('#sandboxName').value,ttlMinutes:Number($('#sandboxTtl').value)}:id==='settingsForm'?{workspaceName:$('#orgName').value,displayName:$('#operatorName').value,theme:themeChoice,language:$('#languagePreference').value,incidentAlerts:$('#incidentAlerts').checked}:{title:$('#ticketTitle').value,description:$('#ticketDescription').value,priority:'normal',conversationId};
 await operation('Saving validated workspace data…',async()=>{if(id==='projectForm')await v1('/assets',payload);else if(id==='sandboxForm'){project=await v1('/sandboxes',payload);selectedProject=project.id;sessionStorage.setItem('rescue-project',selectedProject);page='sandbox';}else if(id==='settingsForm'){prefs=await v1('/settings',payload);toast('Preferences saved on this computer.');}else{await v1('/support/tickets',payload);tickets=(await v1('/support/tickets')).tickets;}if(id!=='settingsForm'){$('#app').inert=false;$('#modalRoot').innerHTML='';}});
});
$('#mobileMenu').onclick=()=>{$('#app').classList.toggle('mobile-open');$('#mobileMenu').setAttribute('aria-expanded',String($('#app').classList.contains('mobile-open')));};$('#mobileScrim').onclick=()=>$('#app').classList.remove('mobile-open');
$('#quickTheme').onclick=()=>{applyTheme(document.body.dataset.theme==='dark'?'light':'dark');if(page==='settings')render();};matchMedia('(prefers-color-scheme:dark)').addEventListener('change',()=>{if(themeChoice==='system')applyTheme('system');});
$('#globalSearch').onclick=()=>{modal('Quick navigation','Search workspace pages.',`<input id="quickFind" aria-label="Search pages" placeholder="Search Overview, Sandbox, AI Support…"><div class="tip-row">${Object.entries(views).map(([id,name])=>btn(name,'searchGo|'+id,'small')).join('')}</div>`);};
const originalAct=act;act=async function(action){if(action.startsWith('searchGo|')){closeModal();return navigate(action.split('|')[1]);}return originalAct(action);};
const baseAct=act;act=async function(action){const [name,arg]=action.split('|');
 if(name==='renameAsset'){modal('Edit project name','The URL and ownership remain unchanged.',`<form id="renameForm"><label for="renameName">Project name</label><input id="renameName" minlength="2" maxlength="70" required value="${esc(assets.find(a=>a.id===selectedAsset).name)}"></form>`,btn('Cancel','closeModal')+'<button class="btn primary" form="renameForm" type="submit">Save name</button>');return;}
 if(name==='archiveAsset'){modal('Remove project from active list','Recoverable removal: history is retained; monitoring is disabled.','<p>Archive this website project?</p>',btn('Cancel','closeModal')+btn('Archive project','confirmArchive','danger'));return;}
 if(name==='confirmArchive'||name==='restoreAsset'){await operation('Updating project archive…',async()=>{await v1('/assets/'+(arg||selectedAsset)+'/'+(name==='confirmArchive'?'archive':'restore'),{});$('#app').inert=false;$('#modalRoot').innerHTML='';});return;}
 if(name==='archivedProjects'){const archived=(await v1('/assets/archived')).assets;modal('Archived projects','Restoration keeps monitoring disabled.',archived.map(a=>`<div class="test-row"><strong>${esc(a.name)}</strong>${btn('Restore','restoreAsset|'+a.id,'small')}</div>`).join('')||'<p>No archived projects.</p>');return;}
 await baseAct(action);
 if(name==='asset'&&$('#modalRoot .modal-footer'))$('#modalRoot .modal-footer').insertAdjacentHTML('beforeend',btn('Edit name','renameAsset')+btn('Remove project','archiveAsset','danger'));
};
const baseProjects=projects;projects=function(){return baseProjects().replace('<div class="page-actions">','<div class="page-actions">'+btn('Archived projects','archivedProjects','','layers'));};
const baseSandbox=sandbox;sandbox=function(){return baseSandbox().replace('<div class="section-space sandbox-toolbar">','<div class="section-space sandbox-toolbar">'+btn('Run browser tests','browserTests','','play',!project?.preview)).replace('>Download receipt</button>',project?.receipts?.length?'>Download receipt</button>':'>Download report</button>');};
const previousAct=act;act=async function(action){if(action==='browserTests'){await operation('Running actual sample browser tests…',async()=>{await v1('/sandboxes/'+project.id+'/tests',{browser:true});tab='tests';});return;}return previousAct(action);};
const baseSupport=support;support=function(){return baseSupport().replace('<div class="tip-row">','<div class="field"><label for="logAttachment">Attach a small text error log (review before sending)</label><input id="logAttachment" type="file" accept=".txt,.log,text/plain"><small class="muted">Up to 1,500 characters. Remove secrets before sending to Meta.</small></div><div class="tip-row">');};
renderGuide=function(g){return String(g.body||g.summary||'').split(/\n\s*\n/).map(block=>block.startsWith('# ')?`<h2>${esc(block.slice(2))}</h2>`:`<p class="muted tiny">${esc(block)}</p>`).join('')+btn('Download guide','downloadGuide','','download');};
document.addEventListener('change',async e=>{if(e.target.id!=='logAttachment')return;const f=e.target.files?.[0];if(!f)return;if(f.size>6000){toast('Use a small excerpt of the error log.','warn');return;}const text=await f.text();if(text.length>1500){toast('Limit the log excerpt to 1,500 characters.','warn');return;}$('#chatInput').value=('Review this error log:\n'+text).slice(0,2000);toast('Log loaded into the message. Review it before selecting Send.');});
document.addEventListener('submit',e=>{if(e.target.id!=='renameForm')return;e.preventDefault();const name=$('#renameName').value;operation('Saving project name…',async()=>{await v1('/assets/'+selectedAsset+'/rename',{name});$('#app').inert=false;$('#modalRoot').innerHTML='';});});
$('#notificationsBtn').onclick=()=>modal('Notifications','Actual active lab incidents',prefs?.incidentAlerts?data.incidents.filter(i=>!['recovered','interrupted'].includes(i.status)).map(i=>btn(i.title+' · '+i.status,'incident|'+i.id,'wide')).join('')||'<p>No active lab incidents.</p>':'<p>Incident alerts are disabled in Settings.</p>');
$('#accessDialog').addEventListener('cancel',e=>e.preventDefault());document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').click();}if(e.key==='Escape'){closeModal();$('#app').classList.remove('mobile-open');}if(e.key==='Tab'&&$('#modalRoot .modal')){const elements=[...$('#modalRoot').querySelectorAll('button:not(:disabled),input,select,textarea,[tabindex="0"]')];const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#primaryNav').insertAdjacentHTML('beforeend','<button class="nav-item" data-page="documentation">'+icon('document')+'Documentation</button><button class="nav-item" data-page="audit">'+icon('shield')+'Audit Trail</button>');
document.body.insertAdjacentHTML('beforeend',btn('AI Support','go|support','primary support-launch','message'));
applyTheme(themeChoice);if(auth)navigate(({monitoring:'projects',supportcenter:'support',agent:'support',lab:'sandbox',connectors:'projects'}[location.hash.slice(1)]||location.hash.slice(1))||'overview');else (async()=>{let identity;try{const response=await fetch('/auth/session');identity=await response.json();}catch{}if(identity?.authorized){auth='session';sessionStorage.setItem('rescue-token',auth);await load();return navigate(location.hash.slice(1)||'projects');}if(identity?.enabled){const dialog=$('#accessDialog');dialog.innerHTML='<div class="eyebrow">IRIZA ACCOUNT</div><h2>Sign in to IRIZA RESCUE</h2><p>Use your existing IRIZA TASTE account. Registration and verification stay with IRIZA.</p><p>'+esc(identity.authenticated?'Your account is signed in but has not been granted RESCUE workspace access.':identity.error||'Sign in to access your recovery workspace.')+'</p><a class="btn primary" href="/signin">Sign in</a> <a class="btn" href="/register">Create an IRIZA account</a>';dialog.showModal();}else $('#accessDialog').showModal();})();
setInterval(async()=>{if(!auth||busy||$('#accessDialog').open||$('#modalRoot').innerHTML||!['overview','maintenance'].includes(page))return;try{await load();render();}catch{}},10000);
